<style scoped lang="scss" src="./update-summary.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import UpdateSummaryModal from "../update-summary-modal/update-summary-modal";
import { IconShape } from "../icon/icon.constants";
import IconButton from "../icon-button/icon-button";
import DesktopOnly from "../desktop-only/desktop-only";
import MobileOnly from "../mobile-only/mobile-only";
import PageIndicator from "../page-indicator/page-indicator";

/**
 * This component is used to display an Update Summary post. This will provide
 * auto navigation to view a "Full Summary" within a modal when the user
 * requests it.
 */
@Component({
  components: {
    UpdateSummaryModal,
    IconButton,
    DesktopOnly,
    MobileOnly,
    PageIndicator,
  },
})
export default class UpdateSummary extends Vue {
  /** Avatar image to render in the Modal update */
  @Prop({ type: String }) modalAvatar;

  @Prop({
    type: Array,
    default: () => [],
  })
  updates;

  @Prop({ type: Boolean }) showEditLinks;
  @Prop({ type: Boolean }) showReadMore;

  currentPage = 0;
  modalOpen = false;
  IconShape = IconShape;

  get showPrevious() {
    return this.currentPage > 0;
  }

  get showNext() {
    const length = this.updates.length;
    return length > 1 && this.currentPage < length - 1;
  }

  get willReadMore() {
    if (this.showReadMore) return true;
    if (this.image) return this.summary.length > 600;
    return this.summary.length > 560;
  }

  get titleText() {
    const update = this.updates[this.currentPage];
    return update.title;
  }

  get summary() {
    const update = this.updates[this.currentPage];
    const summary = update.summary;

    return summary;
  }

  get summaryText() {
    const update = this.updates[this.currentPage];
    const image = update.image;
    const summary = update.summary;

    if (image) {
      return summary.slice(0, 600) + (summary.length > 600 ? "..." : "");
    }

    return summary.slice(0, 560) + (summary.length > 560 ? "..." : "");
  }

  get dateText() {
    const update = this.updates[this.currentPage];
    let date = update.date;

    if (typeof date === "number" || typeof date === "string") {
      date = new Date(date);

      if (date.toDateString() === "Invalid Date") {
        console.warn("Wrong date format");
      }
    }

    if (date) {
      const year = new Intl.DateTimeFormat("en", { year: "numeric" }).format(
        date
      );
      const month = new Intl.DateTimeFormat("en", { month: "long" }).format(
        date
      );
      const day = new Intl.DateTimeFormat("en", { day: "2-digit" }).format(
        date
      );
      return `${month} ${day}, ${year}`;
    }

    return "";
  }

  get date() {
    const update = this.updates[this.currentPage];
    let date = update.date;

    if (typeof date === "number" || typeof date === "string") {
      date = new Date(date);

      if (date.toDateString() === "Invalid Date") {
        console.warn("Wrong date format");
      }
    }

    return date;
  }

  get image() {
    const update = this.updates[this.currentPage];
    return update.image;
  }

  get imageStyle() {
    const update = this.updates[this.currentPage];
    const image = update.image;

    return {
      backgroundImage: `url(${image})`,
    };
  }

  get style() {
    return {};
  }

  handleOpenModal() {
    this.modalOpen = true;

    /**
     * This event is emitted when the user opens the full summary update which
     * is displayed in a modal.
     *
     * @event open
     */
    this.$emit("open");
  }

  handleCloseModal() {
    this.modalOpen = false;
    /**
     * This event is emitted when the user dismisses the modal showing the full
     * update.
     *
     * @event close
     */
    this.$emit("close");
  }

  handleNext() {
    /**
     * This is emitted when the user requests the next summary to be displayed.
     *
     * @event next
     */
    this.currentPage = Math.min(this.updates.length - 1, this.currentPage + 1);
    this.$emit("next", this.currentPage);
  }

  handlePrevious() {
    /**
     * This is emitted when the user requests the previous summary to be
     * displayed when the modal is open.
     *
     * @event previous
     */
    this.currentPage = Math.max(0, this.currentPage - 1);
    this.$emit("previous", this.currentPage);
  }
}

/**  */

</script>

<template>
  <div class="UpdateSummary" :style="style">
    <div class="UpdateSummary__Upper">
      <DesktopOnly>
        <div v-if="image" class="UpdateSummary__Left">
          <div class="UpdateSummary__Image" :style="imageStyle" />
        </div>
      </DesktopOnly>
      <div class="UpdateSummary__Right">
        <div class="UpdateSummary__Head">
          <div class="UpdateSummary__Title">
            <span class="UpdateSummary__Text">{{ titleText }}</span>
          </div>
          <div class="UpdateSummary__Date">
            <span class="UpdateSummary__Text">{{ dateText }}</span>
          </div>
        </div>
        <div ref="summary" class="UpdateSummary__Summary">
          <span v-html="summaryText"></span>
          <span
            v-if="willReadMore"
            class="UpdateSummary__ReadMore"
            @click="handleOpenModal"
          >
            Read More...
          </span>
          <DesktopOnly :media="1024">
            <div class="UpdateSummary__Actions" v-if="showEditLinks">
              <a
                class="UpdateSummary__Actions__Delete"
                @click="$emit('delete', currentPage)"
              >Delete</a>
              <a
                class="UpdateSummary__Actions__Edit"
                @click="$emit('edit', currentPage)"
              >Edit</a>
            </div>
          </DesktopOnly>
        </div>
        <MobileOnly :media="1024">
          <div class="UpdateSummary__Buttons">
            <div v-if="!showPrevious" class="UpdateSummary__Spacer"></div>
            <IconButton
              class="UpdateSummary__Button"
              v-if="showPrevious"
              :shape="IconShape.LEFT"
              @click="handlePrevious"
            />
            <div class="UpdateSummary__Actions" v-if="showEditLinks">
              <a
                class="UpdateSummary__Actions__Delete"
                @click="$emit('delete', currentPage)"
              >Delete</a>
              <a 
                class="UpdateSummary__Actions__Edit"
                @click="$emit('edit', currentPage)"
              >Edit</a>
            </div>
            <IconButton
              class="UpdateSummary__Button"
              v-if="showNext"
              :shape="IconShape.RIGHT"
              @click="handleNext"
            />
            <div v-if="!showNext" class="UpdateSummary__Spacer"></div>
          </div>
        </MobileOnly>
      </div>
      <DesktopOnly :media="1024">
        <div class="UpdateSummary__LeftButton">
          <IconButton
            v-if="showPrevious"
            :shape="IconShape.LEFT"
            @click="handlePrevious"
          />
        </div>
        <div class="UpdateSummary__RightButton">
          <IconButton
            v-if="showNext"
            :shape="IconShape.RIGHT"
            @click="handleNext"
          />
        </div>
      </DesktopOnly>
      <UpdateSummaryModal
        v-if="modalOpen"
        :summary="summary"
        :image="modalAvatar"
        :date="date"
        :title="titleText"
        :previous="showPrevious"
        :next="showNext"
        :currentPage="currentPage + 1"
        :totalPageNumber="updates.length"
        @close="handleCloseModal"
        @previous="handlePrevious"
        @next="handleNext"
      />
    </div>
    <div class="UpdateSummary__Lower">
      <PageIndicator
        :currentPage="currentPage + 1"
        :totalPageNumber="updates.length"
      />
    </div>
  </div>
</template>
